-- 2026-11-22: 9 organismes / dispositifs sociaux, santé et jeunesse référencés par SIAO.
-- Aucun droit automatique, admission médicale conditionnelle, certaines prestations peuvent être payantes.
DO $siao$
DECLARE r record; next_id bigint;
BEGIN
 PERFORM pg_advisory_xact_lock(84690123);
 SELECT COALESCE(MAX(id),0) INTO next_id FROM public.aides_reunion;
 FOR r IN SELECT * FROM jsonb_to_recordset('[{"nom":"ASDR — hospitalisation et soins à domicile Réunion","categorie":"sante","commune":null,"zone_couverte":"La Réunion","organisme":"Association de Soins à Domicile à la Réunion (ASDR)","type_dispositif":"accompagnement","description_fr":"Accompagnement médical complexe à domicile sur prescription, notamment soins palliatifs, nutrition et traitements ; admission médicale obligatoire, prise en charge à vérifier.","demarches_fr":"Demander conseil au médecin prescripteur et contacter l''ASDR au 0262 20 28 20. Ne pas se présenter directement comme ayant droit à une prise en charge.","description_kreol":"Organism ek service-la existe dann répertoire SIAO. Faut vérifi si zot i accueille, les frais éventuels ek bann conditions avan d''aller.","demarches_kreol":"Vérifi sou la fiche SIAO ou contacte l''organism pou demander conditions, horaires ek prix éventuel.","lien_officiel":"https://siao974.re/ressources-du-territoire/asdr-la-reunion/","source_verification":"https://siao974.re/ressources-du-territoire/asdr-la-reunion/","statut_verification":"source_confirmee","date_verification":"2026-11-22","periode_validite":"Source SIAO 974 consultée en novembre 2026 ; effectivité des permanences, montants, conditions et capacité d''accueil à reconfirmer.","score_priorite":68,"besoin_handicap":false,"besoin_retraite":false,"besoin_enfant":false,"besoin_demandeur_emploi":false},{"nom":"ARAR — coordination prestations et hospitalisation à domicile","categorie":"sante","commune":null,"zone_couverte":"La Réunion","organisme":"ARAR","type_dispositif":"accompagnement","description_fr":"Prestations de santé à domicile, coordination d''intervenants et livraison/suivi de matériel ; admission, prescription et financement à valider.","demarches_fr":"Consulter le descriptif ARAR via SIAO puis demander orientation à son équipe médicale ; vérifier les modalités d''admission et les coûts.","description_kreol":"Organism ek service-la existe dann répertoire SIAO. Faut vérifi si zot i accueille, les frais éventuels ek bann conditions avan d''aller.","demarches_kreol":"Vérifi sou la fiche SIAO ou contacte l''organism pou demander conditions, horaires ek prix éventuel.","lien_officiel":"https://siao974.re/ressources-du-territoire/arar-prestations-sante-domicile-psad-had-reunion/","source_verification":"https://siao974.re/ressources-du-territoire/arar-prestations-sante-domicile-psad-had-reunion/","statut_verification":"source_confirmee","date_verification":"2026-11-22","periode_validite":"Source SIAO 974 consultée en novembre 2026 ; effectivité des permanences, montants, conditions et capacité d''accueil à reconfirmer.","score_priorite":68,"besoin_handicap":false,"besoin_retraite":false,"besoin_enfant":false,"besoin_demandeur_emploi":false},{"nom":"Association Santé Mentale Bien-Être Réunion OI — écoute familles","categorie":"sante","commune":null,"zone_couverte":"Est et Sud de La Réunion","organisme":"Association pour la Santé Mentale et le Bien-Être Réunion Océan Indien","type_dispositif":"accompagnement","description_fr":"Écoute et activités pour personnes vivant avec des troubles psychiques et leurs proches ; modalités de groupes de parole et adhésion à confirmer.","demarches_fr":"Contacter l''association via sa fiche SIAO afin de connaître ses groupes et conditions d''accueil.","description_kreol":"Organism ek service-la existe dann répertoire SIAO. Faut vérifi si zot i accueille, les frais éventuels ek bann conditions avan d''aller.","demarches_kreol":"Vérifi sou la fiche SIAO ou contacte l''organism pou demander conditions, horaires ek prix éventuel.","lien_officiel":"https://siao974.re/ressources-du-territoire/association-pour-la-sante-mentale-et-le-bien-etre-reunion-oi/","source_verification":"https://siao974.re/ressources-du-territoire/association-pour-la-sante-mentale-et-le-bien-etre-reunion-oi/","statut_verification":"source_confirmee","date_verification":"2026-11-22","periode_validite":"Source SIAO 974 consultée en novembre 2026 ; effectivité des permanences, montants, conditions et capacité d''accueil à reconfirmer.","score_priorite":68,"besoin_handicap":false,"besoin_retraite":false,"besoin_enfant":true,"besoin_demandeur_emploi":false},{"nom":"EMAAF Réunion — appui aux accueillants familiaux troubles psychiques","categorie":"handicap","commune":null,"zone_couverte":"La Réunion","organisme":"Équipe mobile d''appui aux accueillants familiaux (EMAAF)","type_dispositif":"accompagnement","description_fr":"Appui spécialisé aux accueillants familiaux hébergeant ou souhaitant accueillir des personnes avec troubles psychiques ; ce n''est pas une allocation.","demarches_fr":"Consulter la fiche EMAAF SIAO, puis demander les critères d''orientation aux professionnels concernés.","description_kreol":"Organism ek service-la existe dann répertoire SIAO. Faut vérifi si zot i accueille, les frais éventuels ek bann conditions avan d''aller.","demarches_kreol":"Vérifi sou la fiche SIAO ou contacte l''organism pou demander conditions, horaires ek prix éventuel.","lien_officiel":"https://siao974.re/ressources-du-territoire/emaaf-equipe-mobile-dappui-accueillants-familiaux/","source_verification":"https://siao974.re/ressources-du-territoire/emaaf-equipe-mobile-dappui-accueillants-familiaux/","statut_verification":"source_confirmee","date_verification":"2026-11-22","periode_validite":"Source SIAO 974 consultée en novembre 2026 ; effectivité des permanences, montants, conditions et capacité d''accueil à reconfirmer.","score_priorite":68,"besoin_handicap":true,"besoin_retraite":false,"besoin_enfant":false,"besoin_demandeur_emploi":false},{"nom":"GEM Les Flamboyants — groupe d''entraide mutuelle Saint-Benoît","categorie":"sante","commune":"Saint-Benoît","zone_couverte":"Saint-Benoît","organisme":"GEM Les Flamboyants","type_dispositif":"accompagnement","description_fr":"Pair-aidance, sorties, groupes de parole et activités pour rompre l''isolement en cas de troubles psychiques ; adhésion annoncée à 10 euros/an sur la fiche, à confirmer.","demarches_fr":"Contacter 0262 41 21 61 ou gem.lesflamboyants@gmail.com, 65 bis rue Montfleury à Saint-Benoît, avant visite.","description_kreol":"Organism ek service-la existe dann répertoire SIAO. Faut vérifi si zot i accueille, les frais éventuels ek bann conditions avan d''aller.","demarches_kreol":"Vérifi sou la fiche SIAO ou contacte l''organism pou demander conditions, horaires ek prix éventuel.","lien_officiel":"https://siao974.re/ressources-du-territoire/gem-flamboyants-saint-benoit-troubles-psychiques/","source_verification":"https://siao974.re/ressources-du-territoire/gem-flamboyants-saint-benoit-troubles-psychiques/","statut_verification":"source_confirmee","date_verification":"2026-11-22","periode_validite":"Source SIAO 974 consultée en novembre 2026 ; effectivité des permanences, montants, conditions et capacité d''accueil à reconfirmer.","score_priorite":68,"besoin_handicap":false,"besoin_retraite":false,"besoin_enfant":false,"besoin_demandeur_emploi":false},{"nom":"Cœur Social 974 — aide à domicile et café des aidants","categorie":"senior","commune":null,"zone_couverte":"Toute La Réunion","organisme":"Association Cœur Social 974","type_dispositif":"accompagnement","description_fr":"Services d''aide à domicile pour perte d''autonomie, ateliers prévention, café des aidants, informations et soutien ; certaines prestations peuvent être payantes.","demarches_fr":"Appeler 0262 65 04 66 ou 0692 06 17 85 ou écrire à coeursocial974@gmail.com ; demander le devis et les financements éventuellement accessibles.","description_kreol":"Organism ek service-la existe dann répertoire SIAO. Faut vérifi si zot i accueille, les frais éventuels ek bann conditions avan d''aller.","demarches_kreol":"Vérifi sou la fiche SIAO ou contacte l''organism pou demander conditions, horaires ek prix éventuel.","lien_officiel":"https://siao974.re/ressources-du-territoire/coeur-social-974-saad/","source_verification":"https://siao974.re/ressources-du-territoire/coeur-social-974-saad/","statut_verification":"source_confirmee","date_verification":"2026-11-22","periode_validite":"Source SIAO 974 consultée en novembre 2026 ; effectivité des permanences, montants, conditions et capacité d''accueil à reconfirmer.","score_priorite":68,"besoin_handicap":false,"besoin_retraite":true,"besoin_enfant":false,"besoin_demandeur_emploi":false},{"nom":"Cellule IP PAPH — signaler la maltraitance des aînés et personnes handicapées","categorie":"social","commune":null,"zone_couverte":"Toute La Réunion","organisme":"Département de La Réunion — cellule informations préoccupantes PAPH","type_dispositif":"orientation","description_fr":"Service de signalement des situations de violence, abus financiers, négligence ou danger concernant une personne âgée ou handicapée. Ce n''est pas une allocation.","demarches_fr":"Signaler une préoccupation à celluleIPPAPH@cg974.fr ; numéro national 3977 ou ALMA au 0262 41 53 48. En urgence immédiate, contacter les secours.","description_kreol":"Organism ek service-la existe dann répertoire SIAO. Faut vérifi si zot i accueille, les frais éventuels ek bann conditions avan d''aller.","demarches_kreol":"Vérifi sou la fiche SIAO ou contacte l''organism pou demander conditions, horaires ek prix éventuel.","lien_officiel":"https://siao974.re/ressources-du-territoire/cellule-paph-reunion-signalement-violences/","source_verification":"https://siao974.re/ressources-du-territoire/cellule-paph-reunion-signalement-violences/","statut_verification":"source_confirmee","date_verification":"2026-11-22","periode_validite":"Source SIAO 974 consultée en novembre 2026 ; effectivité des permanences, montants, conditions et capacité d''accueil à reconfirmer.","score_priorite":68,"besoin_handicap":true,"besoin_retraite":true,"besoin_enfant":false,"besoin_demandeur_emploi":false},{"nom":"Unis-Cité La Réunion — service civique et solidarité senior","categorie":"emploi","commune":null,"zone_couverte":"Antennes Saint-Denis, Saint-Benoît, Le Port et Saint-Pierre","organisme":"Unis-Cité La Réunion","type_dispositif":"accompagnement","description_fr":"Service civique des 18-25 ans, jusqu''à 30 ans pour personnes handicapées, programmes de solidarité auprès des aînés et des aidants. Missions et places disponibles à vérifier.","demarches_fr":"Contacter Unis-Cité à reunion@uniscite.fr ou 0692 27 55 71 pour connaître les campagnes et conditions d''inscription.","description_kreol":"Organism ek service-la existe dann répertoire SIAO. Faut vérifi si zot i accueille, les frais éventuels ek bann conditions avan d''aller.","demarches_kreol":"Vérifi sou la fiche SIAO ou contacte l''organism pou demander conditions, horaires ek prix éventuel.","lien_officiel":"https://siao974.re/ressources-du-territoire/unis-cite-la-reunion/","source_verification":"https://siao974.re/ressources-du-territoire/unis-cite-la-reunion/","statut_verification":"source_confirmee","date_verification":"2026-11-22","periode_validite":"Source SIAO 974 consultée en novembre 2026 ; effectivité des permanences, montants, conditions et capacité d''accueil à reconfirmer.","score_priorite":68,"besoin_handicap":false,"besoin_retraite":true,"besoin_enfant":true,"besoin_demandeur_emploi":true},{"nom":"CRIJ Info Jeunes — Guide des Emmerdes 2026 et démarches","categorie":"jeunesse","commune":null,"zone_couverte":"Toute La Réunion","organisme":"CRIJ — Info Jeunes Réunion","type_dispositif":"orientation","description_fr":"Guide d''information 2026 pour jeunes confrontés à des problèmes administratifs, financiers, d''arnaques ou de santé, avec interlocuteurs et démarches. Ne constitue pas un versement.","demarches_fr":"Consulter la ressource CRIJ décrite par le SIAO ; les liens et numéros doivent être vérifiés avant utilisation.","description_kreol":"Organism ek service-la existe dann répertoire SIAO. Faut vérifi si zot i accueille, les frais éventuels ek bann conditions avan d''aller.","demarches_kreol":"Vérifi sou la fiche SIAO ou contacte l''organism pou demander conditions, horaires ek prix éventuel.","lien_officiel":"https://siao974.re/ressources-du-territoire/crij-le-guide-des-emmerdes-conseils-anti-galeres/","source_verification":"https://siao974.re/ressources-du-territoire/crij-le-guide-des-emmerdes-conseils-anti-galeres/","statut_verification":"source_confirmee","date_verification":"2026-11-22","periode_validite":"Source SIAO 974 consultée en novembre 2026 ; effectivité des permanences, montants, conditions et capacité d''accueil à reconfirmer.","score_priorite":68,"besoin_handicap":false,"besoin_retraite":false,"besoin_enfant":false,"besoin_demandeur_emploi":false}]'::jsonb) AS x(
 nom text,categorie text,commune text,zone_couverte text,organisme text,type_dispositif text,
 description_fr text,demarches_fr text,description_kreol text,demarches_kreol text,lien_officiel text,
 source_verification text,statut_verification text,date_verification date,periode_validite text,
 score_priorite int,besoin_handicap boolean,besoin_retraite boolean,besoin_enfant boolean,besoin_demandeur_emploi boolean)
 LOOP
 IF NOT EXISTS(SELECT 1 FROM public.aides_reunion WHERE lower(nom)=lower(r.nom)) THEN
   next_id := next_id+1;
   INSERT INTO public.aides_reunion(id,nom,categorie,commune,zone_couverte,organisme,type_dispositif,description,
   description_fr,demarches_fr,description_kreol,demarches_kreol,lien,lien_officiel,source_verification,
   statut_verification,date_verification,periode_validite,score_priorite,besoin_handicap,besoin_retraite,besoin_enfant,besoin_demandeur_emploi,actif)
   OVERRIDING SYSTEM VALUE
   VALUES(next_id,r.nom,r.categorie,r.commune,r.zone_couverte,r.organisme,r.type_dispositif,r.description_fr,
   r.description_fr,r.demarches_fr,r.description_kreol,r.demarches_kreol,r.lien_officiel,r.lien_officiel,r.source_verification,
   r.statut_verification,r.date_verification,r.periode_validite,r.score_priorite,r.besoin_handicap,r.besoin_retraite,r.besoin_enfant,r.besoin_demandeur_emploi,true);
 END IF;
 END LOOP;
END $siao$;